/** Every preset's `[data-theme]` keys (`themeKeys`), sorted — the built-in theme set `orb` validates `theme` against. */
export function builtInThemeKeys(): string[] {
  return Object.values(THEME_PRESETS).flatMap(themeKeys).sort();
}
